31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.util.UriComponentsBuilder;
44	
45	import jakarta.transaction.Transactional;
46	
47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    /** Dedicated audit trail logger; carries a line for each successful owner create. */
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
103	     *  separated by '@', none of which contain whitespace or a second '@'. */
104	    private static final java.util.regex.Pattern EMAIL_PATTERN =
105	        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
106	
107	    /**
108	     * Normalize the optional email: absent stays absent; when present it must be syntactically
109	     * valid and is lower-cased. Returns {@code false} if present but invalid.
110	     */
111	    private boolean normalizeEmail(Owner owner) {
112	        String email = owner.getEmail();
113	        if (email == null || email.isEmpty()) {
114	            owner.setEmail(null);
115	            return true;
116	        }
117	        if (!EMAIL_PATTERN.matcher(email).matches()) {
118	            return false;
119	        }
120	        owner.setEmail(email.toLowerCase(java.util.Locale.ROOT));
121	        return true;
122	    }
123	
124	    /**
125	     * Return {@code true} when the given (already lower-cased) email is non-null and already used by
126	     * any existing owner, comparing case-insensitively on the lower-cased email.
127	     */
128	    private boolean isEmailAlreadyUsed(String email) {
129	        if (email == null) {
130	            return false;
131	        }
132	        for (Owner existing : this.clinicService.findAllOwners()) {
133	            String existingEmail = existing.getEmail();
134	            if (existingEmail != null && email.equals(existingEmail.toLowerCase(java.util.Locale.ROOT))) {
135	                return true;
136	            }
137	        }
138	        return false;
139	    }
140	
141	    /**
142	     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
143	     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
144	     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
145	     *
146	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
147	     *         a valid E.164 number.
148	     */
149	    private static String toE164(String raw) {
150	        if (raw == null) {
151	            return null;
152	        }
153	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
154	        String digits;
155	        if (cleaned.startsWith("+")) {
156	            digits = cleaned.substring(1);
157	        } else {
158	            if (cleaned.startsWith("0")) {
159	                cleaned = cleaned.substring(1);
160	            }
161	            digits = "61" + cleaned;
162	        }
163	        if (!digits.matches("\\d{8,15}")) {
164	            return null;
165	        }
166	        return "+" + digits;
167	    }
168	
169	    /**
170	     * Validate the national-number length of a canonical E.164 string against its country code:
171	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Numbers carrying any
172	     * other country code are not length-checked here and are accepted. Expects the '+'-prefixed digit
173	     * string produced by {@link #toE164}.
174	     *
175	     * @return {@code true} when the national-number length is correct for the country code.
176	     */
177	    private static boolean hasValidNationalLength(String e164) {
178	        String digits = e164.substring(1);
179	        if (digits.startsWith("61")) {
180	            return digits.length() - 2 == 9;
181	        }
182	        if (digits.startsWith("1")) {
183	            return digits.length() - 1 == 10;
184	        }
185	        return true;
186	    }
187	
188	    /**
189	     * Build the customer code {@code <CITY3>-<LAST3>-<NNNN>}: CITY3 is the upper-cased first three
190	     * letters of the city, LAST3 the upper-cased first three letters of the last name and NNNN a
191	     * per-city 4-digit zero-padded sequence equal to one more than the owners already in that city
192	     * (e.g. {@code SYD-SMI-0007}).
193	     */
194	    private String nextCustomerCode(String city, String lastName) {
195	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
196	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
197	        int sequence = 1;
198	        for (Owner existing : this.clinicService.findAllOwners()) {
199	            if (city.equalsIgnoreCase(existing.getCity())) {
200	                sequence++;
201	            }
202	        }
203	        return String.format("%s-%s-%04d", city3, last3, sequence);
204	    }
205	
206	    /** Common street-type abbreviations expanded during address normalization. */
207	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
208	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
209	
210	    /**
211	     * Normalize an address: {@code null} becomes empty, surrounding whitespace is trimmed, internal
212	     * runs of whitespace are collapsed to a single space, the value is upper-cased and common
213	     * street-type abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE) are expanded token by token.
214	     */
215	    private static String normalizeAddress(String value) {
216	        if (value == null) {
217	            return "";
218	        }
219	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
220	        if (collapsed.isEmpty()) {
221	            return "";
222	        }
223	        String[] tokens = collapsed.split(" ");
224	        StringBuilder sb = new StringBuilder(collapsed.length());
225	        for (int i = 0; i < tokens.length; i++) {
226	            if (i > 0) {
227	                sb.append(' ');
228	            }
229	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
230	        }
231	        return sb.toString();
232	    }
233	
234	    /**
235	     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
236	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
237	     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
238	     */
239	    private static String normalizeForHousehold(String value) {
240	        if (value == null) {
241	            return "";
242	        }
243	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
244	    }
245	
246	    /**
247	     * Return the owners that already share this owner's household, i.e. have the same last name and
248	     * address compared case-insensitively with collapsed whitespace.
249	     */
250	    private List<Owner> householdMembers(Owner owner) {
251	        String lastName = normalizeForHousehold(owner.getLastName());
252	        String address = normalizeForHousehold(owner.getAddress());
253	        List<Owner> members = new java.util.ArrayList<>();
254	        for (Owner existing : this.clinicService.findAllOwners()) {
255	            if (normalizeForHousehold(existing.getLastName()).equals(lastName)
256	                && normalizeForHousehold(existing.getAddress()).equals(address)) {
257	                members.add(existing);
258	            }
259	        }
260	        return members;
261	    }
262	
263	    /**
264	     * Return {@code true} when another owner already shares this owner's household, i.e. has the same
265	     * last name and address compared case-insensitively with collapsed whitespace.
266	     */
267	    private boolean sharesHouseholdWithExisting(Owner owner) {
268	        return !householdMembers(owner).isEmpty();
269	    }
270	
271	    /**
272	     * Count the existing owners that share this owner's first name and last name, compared
273	     * case-insensitively. Used to populate {@code namesakeCount} on create (before this owner is saved).
274	     */
275	    private int namesakeCount(Owner owner) {
276	        String firstName = owner.getFirstName();
277	        String lastName = owner.getLastName();
278	        int count = 0;
279	        for (Owner existing : this.clinicService.findAllOwners()) {
280	            if (firstName != null && lastName != null
281	                && firstName.equalsIgnoreCase(existing.getFirstName())
282	                && lastName.equalsIgnoreCase(existing.getLastName())) {
283	                count++;
284	            }
285	        }
286	        return count;
287	    }
288	
289	    /**
290	     * A stable, shared household identifier derived from the normalized last name and address, so every
291	     * owner in the same household deterministically resolves to the same value.
292	     */
293	    private static String householdIdFor(Owner owner) {
294	        String key = normalizeForHousehold(owner.getLastName()) + "|" + normalizeForHousehold(owner.getAddress());
295	        try {
296	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
297	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
298	            StringBuilder sb = new StringBuilder(24);
299	            for (int i = 0; i < 12; i++) {
300	                sb.append(String.format("%02X", digest[i]));
301	            }
302	            return sb.toString();
303	        }
304	        catch (java.security.NoSuchAlgorithmException e) {
305	            throw new IllegalStateException(e);
306	        }
307	    }
308	
309	    /** Maximum number of owners permitted in a single city. */
310	    private static final int CITY_CAPACITY = 50;
311	
312	    /** Maximum number of owners that may be created (by registrationDate) on a single day. */
313	    private static final int DAILY_CREATE_LIMIT = 100;
314	
315	    /** Number of owners already created on a day beyond which a bulk-signup warning is flagged. */
316	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
317	
318	    /**
319	     * Count the existing owners whose city matches this owner's city, compared case-insensitively.
320	     * Used to enforce the per-city capacity on create (before this owner is saved).
321	     */
322	    private int cityOwnerCount(Owner owner) {
323	        String city = owner.getCity();
324	        int count = 0;
325	        for (Owner existing : this.clinicService.findAllOwners()) {
326	            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
327	                count++;
328	            }
329	        }
330	        return count;
331	    }
332	
333	    /**
334	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
335	     * following Monday, any weekday is returned unchanged. Applied to the effective registration date
336	     * (supplied or defaulted) so that everything derived from it — the stored {@code registrationDate},
337	     * the membership number's year segment and the per-day create limit — uses the adjusted date.
338	     */
339	    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
340	        switch (date.getDayOfWeek()) {
341	            case SATURDAY:
342	                return date.plusDays(2);
343	            case SUNDAY:
344	                return date.plusDays(1);
345	            default:
346	                return date;
347	        }
348	    }
349	
350	    /**
351	     * Count the existing owners whose registrationDate equals the given day. Used to enforce the
352	     * per-day create limit on create (before this owner is saved).
353	     */
354	    private int ownersRegisteredOn(java.time.LocalDate day) {
355	        int count = 0;
356	        for (Owner existing : this.clinicService.findAllOwners()) {
357	            if (day.equals(existing.getRegistrationDate())) {
358	                count++;
359	            }
360	        }
361	        return count;
362	    }
363	
364	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
365	    @Override
366	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
367	        HttpHeaders headers = new HttpHeaders();
368	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
369	        String telephone = toE164(owner.getTelephone());
370	        if (telephone == null || !hasValidNationalLength(telephone)) {
371	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
372	        }
373	        if (!normalizeEmail(owner)) {
374	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
375	        }
376	        String address = normalizeAddress(owner.getAddress());
377	        if (address.isEmpty()) {
378	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
379	        }
380	        owner.setAddress(address);
381	        java.time.LocalDate registrationDate = toBusinessDay(
382	            owner.getRegistrationDate() == null ? java.time.LocalDate.now() : owner.getRegistrationDate());
383	        int ownersRegisteredToday = ownersRegisteredOn(registrationDate);
384	        if (ownersRegisteredToday >= DAILY_CREATE_LIMIT) {
385	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
386	        }
387	        if (cityOwnerCount(owner) >= CITY_CAPACITY) {
388	            return new ResponseEntity<>(HttpStatus.CONFLICT);
389	        }
390	        for (Owner existing : this.clinicService.findAllOwners()) {
391	            String existingTelephone = toE164(existing.getTelephone());
392	            if (telephone.equals(existingTelephone)) {
393	                return new ResponseEntity<>(HttpStatus.CONFLICT);
394	            }
395	        }
396	        if (isEmailAlreadyUsed(owner.getEmail())) {
397	            return new ResponseEntity<>(HttpStatus.CONFLICT);
398	        }
399	        List<Owner> householdMembers = householdMembers(owner);
400	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
401	        if (!sharesHousehold && !householdMembers.isEmpty()) {
402	            return new ResponseEntity<>(HttpStatus.CONFLICT);
403	        }
404	        if (sharesHousehold && !householdMembers.isEmpty()) {
405	            String householdId = householdMembers.stream()
406	                .map(Owner::getHouseholdId)
407	                .filter(id -> id != null && !id.isBlank())
408	                .findFirst()
409	                .orElseGet(() -> householdIdFor(owner));
410	            owner.setHouseholdId(householdId);
411	            for (Owner member : householdMembers) {
412	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
413	                    member.setHouseholdId(householdId);
414	                    this.clinicService.saveOwner(member);
415	                }
416	            }
417	        }
418	        owner.setNamesakeCount(namesakeCount(owner));
419	        owner.setHouseholdSize(householdMembers.size() + 1);
420	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
421	        owner.setTelephone(telephone);
422	        owner.setRegistrationDate(registrationDate);
423	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
424	        this.clinicService.saveOwner(owner);
425	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
426	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
427	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
428	        headers.setLocation(UriComponentsBuilder.newInstance()
429	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
430	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
431	    }
432	
433	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
434	    @Override
435	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
436	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
437	        if (currentOwner == null) {
438	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
439	        }
440	        currentOwner.setAddress(ownerFieldsDto.getAddress());
441	        currentOwner.setCity(ownerFieldsDto.getCity());
442	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
443	        currentOwner.setLastName(ownerFieldsDto.getLastName());
444	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
445	        currentOwner.setEmail(ownerFieldsDto.getEmail());
446	        if (!normalizeEmail(currentOwner)) {
447	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
448	        }
449	        this.clinicService.saveOwner(currentOwner);
450	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
451	    }
452	
453	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
454	    @Transactional
455	    @Override
456	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
457	        Owner owner = this.clinicService.findOwnerById(ownerId);
458	        if (owner == null) {
459	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
460	        }
461	        this.clinicService.deleteOwner(owner);
462	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
463	    }
464	
465	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
466	    @Override
467	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
468	        Owner owner = this.clinicService.findOwnerById(ownerId);
469	        if (owner == null) {
470	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
471	        }
472	        HttpHeaders headers = new HttpHeaders();
473	        Pet pet = petMapper.toPet(petFieldsDto);
474	        owner.setId(ownerId);
475	        pet.setOwner(owner);
476	        pet.getType().setName(null);
477	        this.clinicService.savePet(pet);
478	        PetDto petDto = petMapper.toPetDto(pet);
479	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
480	            .buildAndExpand(pet.getId()).toUri());
481	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
482	    }
483	
484	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
485	    @Override
486	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
487	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
488	        if (currentOwner != null) {
489	            Pet currentPet = this.clinicService.findPetById(petId);
490	            if (currentPet != null) {
491	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
492	                currentPet.setName(petFieldsDto.getName());
493	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
494	                this.clinicService.savePet(currentPet);
495	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
496	            }
497	        }
498	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
499	    }
500	
501	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
502	    @Override
503	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
504	        HttpHeaders headers = new HttpHeaders();
505	        Visit visit = visitMapper.toVisit(visitFieldsDto);
506	        Pet pet = new Pet();
507	        pet.setId(petId);
508	        visit.setPet(pet);
509	        this.clinicService.saveVisit(visit);
510	        VisitDto visitDto = visitMapper.toVisitDto(visit);
511	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
512	            .buildAndExpand(visit.getId()).toUri());
513	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
514	    }
515	
516	
517	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
518	    @Override
519	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
520	        Owner owner = this.clinicService.findOwnerById(ownerId);
521	        if (owner != null) {
522	            Pet pet = owner.getPet(petId);
523	            if (pet != null) {
524	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
525	            }
526	        }
527	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
528	    }
529	}
